('65d29b56-1111-1000-0000-000000000003', '65d29b56-1111-0000-0000-000000000010', 'Metals and Non-Metals', 3, true),
('65d29b56-1111-1000-0000-000000000004', '65d29b56-1111-0000-0000-000000000010', 'Carbon and its Compounds', 4, true),
('65d29b56-1111-1000-0000-000000000005', '65d29b56-1111-0000-0000-000000000010', 'Life Processes', 5, true),
('65d29b56-1111-1000-0000-000000000006', '65d29b56-1111-0000-0000-000000000010', 'Control and Coordination', 6, true),
('65d29b56-1111-1000-0000-000000000007', '65d29b56-1111-0000-0000-000000000010', 'How do Organisms Reproduce?', 7, true),
('65d29b56-1111-1000-0000-000000000008', '65d29b56-1111-0000-0000-000000000010', 'Heredity', 8, true),
('65d29b56-1111-1000-0000-000000000009', '65d29b56-1111-0000-0000-000000000010', 'Light – Reflection and Refraction', 9, true),
('65d29b56-1111-1000-0000-000000000010', '65d29b56-1111-0000-0000-000000000010', 'The Human Eye and the Colourful World', 10, true),
('65d29b56-1111-1000-0000-000000000011', '65d29b56-1111-0000-0000-000000000010', 'Electricity', 11, true),
('65d29b56-1111-1000-0000-000000000012', '65d29b56-1111-0000-0000-000000000010', 'Magnetic Effects of Electric Current', 12, true),
('65d29b56-1111-1000-0000-000000000013', '65d29b56-1111-0000-0000-000000000010', 'Our Environment', 13, true)
INSERT INTO learn_topics (id, chapter_id, title, description, order_index, is_active)
VALUES
('dc491a84-20a8-42d4-85f0-403569ca3d1a', '65d29b56-1111-1000-0000-000000000001', 'Chemical Reactions & Characteristics of Chemical Change', 'Introduction to chemical reactions, evidence of chemical change (evolution of gas, change in temperature, colour, state) and word equations.', 1, true),
('e58be5b2-8082-47f8-88fe-f68a22e01a0b', '65d29b56-1111-1000-0000-000000000001', 'Writing and Balancing Chemical Equations', 'Law of conservation of mass, skeleton equations, step-by-step hit-and-trial balancing method and states of matter notation.', 2, true),
('3d488e28-8363-475a-a69e-ea2ab1eda064', '65d29b56-1111-1000-0000-000000000001', 'Combination Reactions & Practical: Action of Water on Quicklime', 'Exothermic synthesis reactions with CaO (quicklime) forming Ca(OH)2 (slaked lime) and whitewashing application.', 3, true),
('2a2a244f-d563-4e15-ac76-30a3ef2789e6', '65d29b56-1111-1000-0000-000000000001', 'Decomposition Reactions: Thermal, Electrolytic & Photolytic', 'Endothermic breakdown reactions: Heating of FeSO4 crystals, Pb(NO3)2 decomposition, electrolysis of water, and AgCl/AgBr photochemical decomposition.', 4, true),
('855d58c3-caca-4016-8633-f616305c1f48', '65d29b56-1111-1000-0000-000000000001', 'Displacement Reactions & Practical: Iron Nails in Copper Sulphate', 'Single displacement reactions based on reactivity series; Fe + CuSO4 blue to pale green transition and Cu deposition.', 5, true),
('61988f29-0976-429f-a0ef-131451df9d74', '65d29b56-1111-1000-0000-000000000001', 'Double Displacement Reactions & Precipitation', 'Exchange of ions: Reaction of Sodium sulphate and Barium chloride forming insoluble white BaSO4 precipitate.', 6, true),
('45bb2883-5fec-4835-ad5c-886bf57b994c', '65d29b56-1111-1000-0000-000000000001', 'Oxidation, Reduction and Redox Reactions', 'Gain and loss of oxygen and hydrogen, oxidizing and reducing agents, electron transfer concept, corrosion of metals and rancidity in food.', 7, true),
('51f5a377-aa33-45cb-8e7d-7410d3001075', '65d29b56-1111-1000-0000-000000000002', 'Acids and Bases: Definition and Ions (H+ and OH-)', 'Arrhenius concept: Furnishing of hydronium H3O+ and hydroxide OH- ions, strong vs weak acids and bases, and dilution precautions.', 1, true),
('ac976124-41af-479b-b5ca-310e66532ef3', '65d29b56-1111-1000-0000-000000000002', 'Indicators & Chemical Properties of Acids and Bases', 'Natural (litmus, turmeric), synthetic (methyl orange, phenolphthalein), olfactory indicators; Reaction with metals, metal carbonates, hydrogen carbonates and neutralization.', 2, true),
('17af1aff-181f-4adf-a654-28ae76871ef0', '65d29b56-1111-1000-0000-000000000002', 'The pH Scale and Importance of pH in Everyday Life', 'Concept of pH scale (0 to 14), neutral, acidic and alkaline solutions, pH in digestive system, tooth decay, soil testing, acid rain and self-defense by animals.', 3, true),
('cdc680ff-7e03-4c4f-89d4-d27ac3b8c3ea', '65d29b56-1111-1000-0000-000000000002', 'Sodium Hydroxide (Chlor-Alkali Process) & Bleaching Powder', 'Electrolysis of brine producing NaOH, Cl2, and H2; Synthesis, properties and industrial uses of Bleaching powder CaOCl2.', 4, true),
('baf28e89-51fc-4f0a-aab1-d41e9d66cabf', '65d29b56-1111-1000-0000-000000000002', 'Baking Soda and Washing Soda', 'Solvay process overview: Sodium hydrogen carbonate (NaHCO3) and Sodium carbonate decahydrate (Na2CO3.10H2O), properties and domestic/industrial uses.', 5, true),
('efdf00db-7685-422a-aa49-c9328a3ffa1c', '65d29b56-1111-1000-0000-000000000002', 'Plaster of Paris and Water of Crystallization', 'Hydrated salts, copper sulphate crystals, heating of Gypsum (CaSO4.2H2O) to form Plaster of Paris (CaSO4.1/2H2O) and its medical/decorative uses.', 6, true),
('76db8cd3-bcfb-4dc6-a018-19b4966d3bf9', '65d29b56-1111-1000-0000-000000000003', 'Physical Properties of Metals and Non-Metals', 'Malleability, ductility, electrical and thermal conductivity, sonority, lustrous nature, exceptions (mercury, iodine, diamond, graphite, gallium, caesium).', 1, true),
('5cc9c8d9-e5cc-4a3b-a6f3-5e1f0ea83e46', '65d29b56-1111-1000-0000-000000000003', 'Chemical Properties of Metals & Amphoteric Oxides', 'Reaction with oxygen, basic oxides, amphoteric oxides (Al2O3, ZnO), reaction with water (cold, hot, steam), and reactions with dilute acids.', 2, true),
('24d6883e-c40b-4751-b2a7-554cbe30f9c6', '65d29b56-1111-1000-0000-000000000003', 'Reactivity Series of Metals & Practical Salt Displacement', 'Arrangement of metals in decreasing order of reactivity: Action of Zn, Fe, Cu, and Al on ZnSO4, FeSO4, CuSO4, and Al2(SO4)3 solutions.', 3, true),
('b85f99f5-a071-41c9-b9ec-de6df766a290', '65d29b56-1111-1000-0000-000000000003', 'Ionic Compounds: Formation and Properties', 'Transfer of electrons between metals and non-metals (NaCl, MgCl2), electron dot structures, physical nature, high melting/boiling points, solubility and electrical conductivity.', 4, true),
('d6befad8-de75-4734-a3a7-01510757298c', '65d29b56-1111-1000-0000-000000000003', 'Basic Metallurgical Processes: Extraction of Metals', 'Occurrence of metals, minerals vs ores, gangue removal, extraction of metals of low, medium (roasting and calcination) and high reactivity (electrolytic reduction).', 5, true),
('125cb708-35a2-4cb1-810b-d4c9d71bdd91', '65d29b56-1111-1000-0000-000000000003', 'Refining of Metals, Corrosion and its Prevention', 'Electrolytic refining of copper, conditions for rusting of iron, prevention by painting, oiling, galvanisation, chrome plating, anodising and making alloys (steel, brass, bronze, solder).', 6, true),
('169eea40-8735-4c14-a4b5-42ec77196368', '65d29b56-1111-1000-0000-000000000004', 'Covalent Bonding and Versatile Nature of Carbon', 'Tetravalency and catenation, single, double and triple covalent bonds in H2, O2, N2, CH4, and properties of covalent compounds.', 1, true),
('8fd942c1-1d69-4489-8371-678669c14e26', '65d29b56-1111-1000-0000-000000000004', 'Saturated and Unsaturated Hydrocarbons: Alkanes, Alkenes & Alkynes', 'Straight chain, branched chain and cyclic hydrocarbons; Structural isomerism in butane and pentane.', 2, true),
('4bc82fc9-3f3b-4927-95b0-f6ef135af542', '65d29b56-1111-1000-0000-000000000004', 'Functional Groups and Homologous Series', 'Heteroatoms, halogens, alcohol, aldehyde, ketone, carboxylic acid groups, homologous series characteristics and gradation in physical properties.', 3, true),
('4c33bddc-65f6-4928-9c32-825e0ce8125d', '65d29b56-1111-1000-0000-000000000004', 'IUPAC Nomenclature of Carbon Compounds', 'Systematic IUPAC naming rules for alkanes, alkenes, alkynes, alcohols, haloalkanes, aldehydes, ketones, and carboxylic acids.', 4, true),
('edebb56b-478d-49d6-9199-c8b805bde770', '65d29b56-1111-1000-0000-000000000004', 'Chemical Properties of Carbon Compounds', 'Combustion (clean vs sooty flame), oxidation with alkaline KMnO4 / acidified K2Cr2O7, addition reactions (hydrogenation with Ni/Pd catalyst) and substitution reactions.', 5, true),
('3b150dd5-2345-4e51-988b-c600dd31cafa', '65d29b56-1111-1000-0000-000000000004', 'Important Carbon Compounds: Ethanol and Ethanoic Acid', 'Properties and reactions of ethanol (with sodium, dehydration to ethene) and ethanoic acid (esterification, saponification, reaction with carbonates and hydrogen carbonates).', 6, true),
('ff9a3df4-d68b-44cd-bd63-6a9b209aeda1', '65d29b56-1111-1000-0000-000000000004', 'Soaps, Detergents and Cleansing Action', 'Structure of soap molecules (hydrophilic head & hydrophobic tail), micelle formation, emulsification of grease, and scum formation in hard water vs synthetic detergents.', 7, true),
('9d4acc83-3356-4363-86c0-0e57d91a2b4f', '65d29b56-1111-1000-0000-000000000005', 'Introduction to Life Processes & Autotrophic Nutrition', 'What are life processes; Photosynthesis equation, light & dark reactions, role of chlorophyll, and stomatal opening/closing mechanism with leaf peel practical.', 1, true),
('f8a7c453-1271-4e90-b53d-6f345ba8d538', '65d29b56-1111-1000-0000-000000000005', 'Heterotrophic Nutrition and Human Digestive System', 'Holozoic, saprophytic and parasitic nutrition; Ingestion, digestion, absorption, assimilation, and egestion in Amoeba and Human alimentary canal enzymes.', 2, true),
('8ef7173e-9608-4733-af41-2e8348e52c68', '65d29b56-1111-1000-0000-000000000005', 'Respiration: Aerobic vs Anaerobic & Human Respiratory System', 'Three pathways of glucose breakdown (cytoplasm to pyruvate, anaerobic in yeast, muscle cells under oxygen lack, aerobic in mitochondria), ATP, and Human lungs & alveoli.', 3, true),
('0e3a8545-a4b4-494d-9847-2e1ca4f0c0f3', '65d29b56-1111-1000-0000-000000000005', 'Transportation in Human Beings: Heart, Blood & Lymph', 'Internal structure of human heart, double circulation (pulmonary and systemic), blood vessels (arteries, veins, capillaries), blood pressure and lymphatic system.', 4, true),
('c45b3374-f09c-4ed5-87b0-f61a1ad436f7', '65d29b56-1111-1000-0000-000000000005', 'Transportation in Plants: Xylem and Phloem', 'Ascent of sap, root pressure, transpiration pull in xylem; Translocation of sucrose and amino acids through phloem using metabolic energy (ATP).', 5, true),
('8e2cbe28-0b51-4b0e-846e-c1c4c69cbe7d', '65d29b56-1111-1000-0000-000000000005', 'Excretion in Human Beings and Plants', 'Human excretory system, structure and functioning of nephron (ultrafiltration, selective reabsorption, tubular secretion), artificial kidney (dialysis) and plant excretion methods.', 6, true),
('f0d5d6ec-84e9-4130-a18a-119303ebbf6c', '65d29b56-1111-1000-0000-000000000006', 'Nervous System, Neuron Structure & Nerve Impulses', 'Receptors, anatomy of neuron (cyton, dendrite, axon), neuromuscular junction and electrochemical impulse transmission across synapse.', 1, true),
('6de7e3ec-16a9-440a-b4f1-b9ce54b24fc4', '65d29b56-1111-1000-0000-000000000006', 'Reflex Action and Reflex Arc', 'Involuntary rapid response mechanism, stimulus, sensory neuron, relay neuron in spinal cord, motor neuron, and effector muscles.', 2, true),
('5cd597ee-546a-4554-93af-459816b6d56d', '65d29b56-1111-1000-0000-000000000006', 'Human Brain: Structure, Meninges and Functions', 'Central Nervous System (CNS) and Peripheral Nervous System (PNS); Forebrain (cerebrum, thinking), Midbrain, and Hindbrain (cerebellum, pons, medulla oblongata).', 3, true),
('434d29e7-b97b-4e5c-bbf5-869861fb6c3d', '65d29b56-1111-1000-0000-000000000006', 'Coordination in Plants: Tropic and Nastic Movements', 'Movement dependent on growth: Phototropism, Geotropism, Hydrotropism, Chemotropism, Thigmotropism; Movement independent of growth (Touch-me-not plant Mimosa pudica).', 4, true),
('74067fd6-c87d-4257-abba-d8591b823ef5', '65d29b56-1111-1000-0000-000000000006', 'Plant Hormones (Phytohormones)', 'Synthesis and physiological functions of Auxins (cell elongation), Gibberellins (stem elongation), Cytokinins (cell division), Abscisic acid (growth inhibitor, wilting) and Ethylene.', 5, true),
('3249fd52-8db8-4220-a714-c67857a01111', '65d29b56-1111-1000-0000-000000000006', 'Hormones in Animals and Endocrine Glands', 'Chemical coordination: Pituitary (Growth hormone), Thyroid (Thyroxine & Iodine role), Adrenal (Adrenaline & fight-or-flight response), Pancreas (Insulin & Diabetes), and Testes/Ovaries.', 6, true),
('e57689a3-d671-404c-b99c-193ba4ae2d33', '65d29b56-1111-1000-0000-000000000007', 'Importance of Variation and DNA Replication', 'DNA replication in cellular reproduction, biochemical variations, survival advantage of variations in changing environments.', 1, true),
('5a764482-8bc0-4bd7-8aae-b1b507729593', '65d29b56-1111-1000-0000-000000000007', 'Asexual Reproduction Modes', 'Binary fission (Amoeba, Leishmania), multiple fission (Plasmodium), budding (Yeast, Hydra), regeneration (Planaria), fragmentation (Spirogyra), and spore formation (Rhizopus).', 2, true),
('c3ff74bd-1960-4044-a482-b195f8d1bf35', '65d29b56-1111-1000-0000-000000000007', 'Vegetative Propagation in Plants and Tissue Culture', 'Natural vegetative propagation (roots, stems, leaves - Bryophyllum) and artificial methods (cutting, layering, grafting); Advantages and micropropagation.', 3, true),
('9741cb58-dbfe-4958-b474-ff2d77c022cd', '65d29b56-1111-1000-0000-000000000007', 'Sexual Reproduction in Flowering Plants', 'Structure of bisexual flower (sepals, petals, stamen, carpel), pollination (self vs cross), pollen tube growth, double fertilization, and seed germination with embryo structure.', 4, true),
('3fce9b40-a0ec-4ad3-9437-d912bc129f04', '65d29b56-1111-1000-0000-000000000007', 'Human Male and Female Reproductive Systems', 'Primary and secondary sexual characteristics; Male organs (testes, vas deferens, seminal vesicles, prostate, penis) and Female organs (ovaries, fallopian tubes, uterus, cervix, vagina).', 5, true),
('37b53b95-060e-433f-84be-9b4e812648b9', '65d29b56-1111-1000-0000-000000000007', 'Menstrual Cycle, Fertilization and Embryo Development', 'Monthly cycle when egg is not fertilized, role of placenta in nourishing the developing embryo, and gestation period.', 6, true),
('3c20a34e-92e5-4866-9665-5b75c6917676', '65d29b56-1111-1000-0000-000000000007', 'Reproductive Health, Contraceptive Methods & STDs', 'Need for family planning; Mechanical barrier methods (condoms), chemical methods (oral pills), IUDs (Copper-T), surgical methods (vasectomy, tubectomy); STDs (Bacterial: Gonorrhoea, Syphilis; Viral: Warts, HIV/AIDS).', 7, true),
('e6af9b28-8e51-4fee-a0dd-624cfacc1af0', '65d29b56-1111-1000-0000-000000000008', 'Heredity and Inherited Traits', 'Transmission of traits from parents to offspring, common body design vs variations, rules for the inheritance of traits.', 1, true),
('f2ce8350-3627-49aa-af88-25ff9fcbc6aa', '65d29b56-1111-1000-0000-000000000008', 'Mendel’s Experiments: Monohybrid Cross and Laws of Inheritance', 'Selection of pea plant (Pisum sativum), TT x tt cross, F1 generation, F2 phenotypic ratio (3:1) and genotypic ratio (1:2:1), dominant vs recessive traits, and Law of Segregation.', 2, true),
('3fde3bf9-f8eb-43a1-9888-3a3c2a4aa0a5', '65d29b56-1111-1000-0000-000000000008', 'Mendel’s Experiments: Dihybrid Cross and Independent Assortment', 'Inheritance of two independent traits (Round Yellow RRYY x Wrinkled Green rryy), F2 dihybrid phenotypic ratio (9:3:3:1) and Law of Independent Assortment.', 3, true),
('906c53bf-e759-4726-bfd1-6a52c59b7edc', '65d29b56-1111-1000-0000-000000000008', 'How do Genes Express Traits? (Mechanism of Expression)', 'Cellular DNA as information source for proteins, enzymes and hormones controlling plant height and traits.', 4, true),
('3d68d40f-a74a-441d-9226-39d744c96c74', '65d29b56-1111-1000-0000-000000000008', 'Sex Determination in Human Beings', 'Environmental vs genetic sex determination; Human karyotype (22 pairs of autosomes + 1 pair of sex chromosomes), XX female, XY male, and equal probability of male/female child.', 5, true),
('a8316417-c3af-4a35-9efb-2b7b0568829e', '65d29b56-1111-1000-0000-000000000009', 'Spherical Mirrors: Fundamentals and Terminology', 'Reflection of light, concave and convex mirrors, pole (P), centre of curvature (C), radius of curvature (R), principal axis, principal focus (F), and focal length relationship (R = 2f).', 1, true),
('a84a022b-735d-48a4-a062-827a52d6620c', '65d29b56-1111-1000-0000-000000000009', 'Image Formation by Concave and Convex Mirrors', 'Rules for ray diagrams (parallel ray, focal ray, centre ray, oblique ray); 6 positions for concave mirror and 2 positions for convex mirror; Nature, position, and relative size of images.', 2, true),
('652458de-2397-43a0-ba9b-debcbe6d03ee', '65d29b56-1111-1000-0000-000000000009', 'Sign Convention, Mirror Formula and Magnification', 'New Cartesian Sign Convention; Mirror formula 1/f = 1/v + 1/u, magnification m = h''/h = -v/u, and step-by-step numerical problem solving.', 3, true),
('4c59d3ea-549b-48a9-aa80-1896a1f7aee0', '65d29b56-1111-1000-0000-000000000009', 'Refraction of Light and Laws of Refraction', 'Bending of light across optical media, optical density, laws of refraction, Snell''s law (sin i / sin r = constant), and rectangular glass slab ray tracing practical.', 4, true),
('bf810d2a-5724-469f-a670-8a31ab408dad', '65d29b56-1111-1000-0000-000000000009', 'Refractive Index and Speed of Light in Media', 'Absolute refractive index (n = c/v), relative refractive index (n21 = v1/v2), relation with optical density, and speed of light in various media.', 5, true),
('4ca4cd99-73a0-4292-b10d-6827bec78d17', '65d29b56-1111-1000-0000-000000000009', 'Refraction by Spherical Lenses & Ray Diagrams', 'Convex (converging) and concave (diverging) lenses, optical centre (O), principal focus, ray diagram rules, image formation for all object positions.', 6, true),
('4bd5bf87-1fb5-439b-9de9-b71f5689c660', '65d29b56-1111-1000-0000-000000000009', 'Lens Formula, Magnification and Power of a Lens', 'Lens formula 1/f = 1/v - 1/u, linear magnification m = h''/h = v/u; Power of lens P = 1/f (in metres), Dioptre unit (D), convex lens positive power, concave lens negative power, and lens combinations.', 7, true),
('60b6a801-d1d0-46da-a9dc-825032e685fd', '65d29b56-1111-1000-0000-000000000010', 'Structure of the Human Eye and Power of Accommodation', 'Cornea, iris, pupil, crystalline lens, ciliary muscles, retina, rods, cones, optic nerve; Near point (25 cm), far point (infinity), and focal length adjustment.', 1, true),
('5cf40655-abf5-48fc-b4c3-c213493e9264', '65d29b56-1111-1000-0000-000000000010', 'Defects of Vision and their Optical Correction', 'Myopia (short-sightedness, concave lens correction), Hypermetropia (far-sightedness, convex lens correction), Presbyopia (bifocal lens) and Cataract.', 2, true),
('1b21b8f3-1957-47e5-b48c-5cc54b00fcd3', '65d29b56-1111-1000-0000-000000000010', 'Refraction of Light through a Triangular Glass Prism', 'Prism ray tracing practical: Angle of incidence, angle of refraction, angle of emergence, and angle of deviation (D).', 3, true),
('9a88aa53-5274-4b84-b50a-32e8570e8fd3', '65d29b56-1111-1000-0000-000000000010', 'Dispersion of White Light and Rainbow Formation', 'Newton’s experiment, splitting of white light into spectrum (VIBGYOR), recombination of spectrum with inverted prism, and natural internal reflection in raindrops forming rainbows.', 4, true),
('49991722-b7aa-4101-bac8-ec8fd3d4f6bc', '65d29b56-1111-1000-0000-000000000010', 'Atmospheric Refraction & Everyday Optical Phenomena', 'Optical density gradation in atmosphere; Twinkling of stars (point sources vs extended planets), advanced sunrise and delayed sunset by 2 minutes.', 5, true),
('fad5fb88-d908-4ac4-a1ea-31df590e5129', '65d29b56-1111-1000-0000-000000000010', 'Scattering of Light and Tyndall Effect', 'Rayleigh scattering law (intensity proportional to 1/lambda^4), Tyndall effect in colloidal solutions and smoke/canopy, why clear sky is blue, why clouds appear white, and red danger signals.', 6, true),
('42ba0969-96e7-4764-825a-c8b5702fa513', '65d29b56-1111-1000-0000-000000000011', 'Electric Charge, Current and Electric Circuit', 'Quantization of charge (Q = ne), definition of electric current (I = Q/t), Ampere unit, flow of electrons vs conventional current, ammeter connection.', 1, true),
('63b84ece-ae6f-4a5f-a564-90b92fe01073', '65d29b56-1111-1000-0000-000000000011', 'Electric Potential, Potential Difference and Voltmeter', 'Work done in moving a unit charge (V = W/Q), Volt unit, battery as potential difference maintainer, and voltmeter high resistance parallel connection.', 2, true),
('4499170e-029c-441c-aee2-31984b70eedb', '65d29b56-1111-1000-0000-000000000011', 'Ohm’s Law and V-I Characteristic Graph', 'Statement of Ohm’s law (V = IR), linear V-I relationship, resistance definition, Ohm unit, rheostat, and experimental verification.', 3, true),
('9570e5e5-29e4-4df2-b1b0-5f1925ca9fbd', '65d29b56-1111-1000-0000-000000000011', 'Factors Affecting Resistance & Electrical Resistivity', 'Resistance dependence on length (R proportional to l), cross-sectional area (R proportional to 1/A), temperature, and material nature; Resistivity (rho = RA/l) in Ohm-metre, conductors vs alloys vs insulators.', 4, true),
('31abb6bc-1303-4011-acf7-c83343cba2f3', '65d29b56-1111-1000-0000-000000000011', 'Resistors in Series Combination', 'Constant current, potential division (V = V1 + V2 + V3), equivalent resistance Rs = R1 + R2 + R3, and disadvantages in domestic circuits.', 5, true),
('1c4c071f-5791-4842-b140-148d961b8567', '65d29b56-1111-1000-0000-000000000011', 'Resistors in Parallel Combination', 'Constant potential difference, current division (I = I1 + I2 + I3), equivalent resistance 1/Rp = 1/R1 + 1/R2 + 1/R3, and advantages in household wiring.', 6, true),
('0e607843-8684-4a6d-8118-ca2d27bcb552', '65d29b56-1111-1000-0000-000000000011', 'Heating Effect of Electric Current (Joule’s Law of Heating)', 'Conversion of electrical energy into thermal energy: Joule''s law H = I^2Rt = VIt = (V^2/R)t, practical applications in electric heaters, toasters, and electric fuse.', 7, true),
('a0502169-8fbc-4b03-98a7-b6256a69e9c7', '65d29b56-1111-1000-0000-000000000011', 'Electric Power, Interrelations and Commercial Unit of Energy', 'Rate of electrical energy consumption: P = VI = I^2R = V^2/R, Watt unit, commercial unit of energy (1 kWh = 3.6 x 10^6 Joules), and household electricity bill calculations.', 8, true),
('c27a70aa-3c55-4f3d-bd53-2bbeee7682bc', '65d29b56-1111-1000-0000-000000000012', 'Magnetic Field and Magnetic Field Lines', 'Oersted’s experiment, magnetic field definition, properties of magnetic field lines (closed continuous curves, tangent gives direction, lines never intersect), and compass needle deflection.', 1, true),
('76bb7312-5091-458e-abd2-9b788733716e', '65d29b56-1111-1000-0000-000000000012', 'Magnetic Field due to a Straight Current-Carrying Conductor', 'Concentric field circles, factors affecting field strength (proportional to current, inversely proportional to distance), and Right-Hand Thumb Rule.', 2, true),
('4afd3051-f22f-4b5f-bec9-485e18eb6a2b', '65d29b56-1111-1000-0000-000000000012', 'Magnetic Field due to a Circular Loop and Solenoid', 'Superposition of magnetic lines in a circular loop, Clock Face rule, magnetic field of a long helical solenoid resembling a bar magnet, and Electromagnet construction.', 3, true),
('83fd1411-1474-44e1-ad21-98a6e5fcb01e', '65d29b56-1111-1000-0000-000000000012', 'Force on a Current-Carrying Conductor & Fleming’s Left-Hand Rule', 'Ampere’s observation of mutual force, conditions for maximum force (perpendicular orientation), and Fleming’s Left-Hand Rule (Thumb-Motion, Forefinger-Field, Middle finger-Current).', 4, true),
('b614e659-9206-40f4-a24a-5b32df36c95b', '65d29b56-1111-1000-0000-000000000012', 'Direct Current (DC) vs Alternating Current (AC)', 'Unidirectional current vs periodically reversing current, AC frequency in India (50 Hz, reverses direction every 1/100 s), and major transmission advantages of AC over DC.', 5, true),
('61ab9452-240f-4ae8-b52a-11e74e5c7345', '65d29b56-1111-1000-0000-000000000012', 'Domestic Electric Circuits and Safety Devices', 'Live wire (red/brown, 220V), Neutral wire (black/blue, 0V), Earth wire (green/yellow), earthing of metallic appliances, electric fuse, short-circuiting, and overloading causes.', 6, true),
('dcbb75cc-e824-4028-8aff-3b0a0c70b509', '65d29b56-1111-1000-0000-000000000013', 'Ecosystem and its Components (Biotic and Abiotic)', 'Natural (forest, pond, lake) vs artificial (crop field, aquarium) ecosystems; Producers (autotrophs), consumers (herbivores, carnivores, omnivores, parasites) and decomposers (bacteria, fungi).', 1, true),
('de8a3f6e-3484-4d41-afca-7c0e7bd08fb1', '65d29b56-1111-1000-0000-000000000013', 'Food Chains, Food Webs and Trophic Levels', 'Linear feeding relationships, network of interconnected food chains (food web), first, second, third, and fourth trophic levels.', 2, true),
('a5a7ec67-3a5e-4366-bb36-557379139ae5', '65d29b56-1111-1000-0000-000000000013', 'Energy Flow in Ecosystems and The 10% Law', 'Unidirectional flow of solar energy, Lindeman''s 10% law of energy transfer between successive trophic levels, and loss of energy as heat.', 3, true),
('f293d870-d1b5-4a79-8091-9c5fe3134eb9', '65d29b56-1111-1000-0000-000000000013', 'Biological Magnification (Biomagnification)', 'Accumulation of non-biodegradable harmful chemicals/pesticides (like DDT) in progressive trophic levels, with maximum concentration in top carnivores/humans.', 4, true),
('21d3261e-f43c-46f5-8231-1a027345e433', '65d29b56-1111-1000-0000-000000000013', 'Ozone Layer Depletion and Prevention', 'Formation of ozone (O3) in stratosphere by UV photolysis of O2, shielding harmful UV-B radiation, damage caused by Chlorofluorocarbons (CFCs), and Montreal Protocol 1987.', 5, true),
('2fcae6f2-0ced-4689-b3de-f69b62dd1376', '65d29b56-1111-1000-0000-000000000013', 'Waste Generation, Management and Eco-Friendly Practices', 'Biodegradable vs non-biodegradable garbage, environmental hazards of plastics, modern disposal methods: landfilling, composting, vermicomposting, recycling, incineration and sewage treatment.', 6, true)
